  1	--------------------------------------------------------------------------------
  2	-- uart_tx.vhd
  3	-- Purpose : One-byte UART transmitter, 8N1 (1 start bit, 8 data bits LSB first,
  4	--           no parity, 1 stop bit). Sub-block of Lab-DEBUG.
  5	-- Design  : docs/architecture/subsystems/debug.md §7, §8, §9
  6	-- Reqs    : REQ-DEBUG-002, REQ-DEBUG-008, REQ-DEBUG-009, REQ-PERF-001
  7	-- Author  : Hande Eryilmaz
  8	-- AI      : AI-assisted (Claude Opus 5.5, claude.ai chat, 2026-09-26), AI-0004
  9	--
 10	-- Behaviour
 11	--   * tx_start_in is sampled only in S_IDLE; pulses while sending are ignored.
 12	--   * Every bit lasts exactly G_CLKS_PER_BIT clock cycles.
 13	--   * tx_done_out is a one-cycle pulse after the stop bit has lasted a full
 14	--     bit period; the transmitter is idle again in that same cycle.
 15	--   * txd_out is a register (glitch-free line), '1' when idle and during reset.
 16	--------------------------------------------------------------------------------
 17	library ieee;
 18	use ieee.std_logic_1164.all;
 19	
 20	entity uart_tx is
 21	    generic (
 22	        G_CLKS_PER_BIT : positive := 100   -- 100 MHz / 1 000 000 baud (DEC-005)
 23	    );
 24	    port (
 25	        clock_in    : in  std_logic;
 26	        reset_in    : in  std_logic;                     -- active high, synchronous
 27	        tx_start_in : in  std_logic;                     -- 1-cycle pulse
 28	        tx_data_in  : in  std_logic_vector(7 downto 0);  -- sampled with tx_start_in
 29	        txd_out     : out std_logic;                     -- serial line, idle '1'
 30	        tx_done_out : out std_logic                      -- 1-cycle pulse, frame finished
 31	    );
 32	end entity uart_tx;
 33	
 34	architecture rtl of uart_tx is
 35	
 36	    constant C_LAST_BIT : natural := 9;   -- bit index of the stop bit (0 = start bit)
 37	
 38	    type t_state is (S_IDLE, S_SENDING);
 39	
 40	    signal state     : t_state := S_IDLE;
 41	    -- frame shift register: (9) stop bit, (8 downto 1) data, (0) start bit
 42	    signal shift_reg : std_logic_vector(C_LAST_BIT downto 0) := (others => '1');
 43	    signal clk_cnt   : natural range 0 to G_CLKS_PER_BIT - 1 := 0;
 44	    signal bit_cnt   : natural range 0 to C_LAST_BIT := 0;
 45	    signal txd_reg   : std_logic := '1';
 46	    signal done_reg  : std_logic := '0';
 47	
 48	begin
 49	
 50	    process (clock_in)
 51	    begin
 52	        if rising_edge(clock_in) then
 53	            done_reg <= '0';                              -- default: no pulse
 54	
 55	            if reset_in = '1' then
 56	                state     <= S_IDLE;
 57	                shift_reg <= (others => '1');
 58	                clk_cnt   <= 0;
 59	                bit_cnt   <= 0;
 60	                txd_reg   <= '1';
 61	            else
 62	                case state is
 63	
 64	                    when S_IDLE =>
 65	                        txd_reg <= '1';
 66	                        if tx_start_in = '1' then
 67	                            shift_reg <= '1' & tx_data_in & '0';
 68	                            txd_reg   <= '0';                 -- start bit begins now
 69	                            clk_cnt   <= 0;
 70	                            bit_cnt   <= 0;
 71	                            state     <= S_SENDING;
 72	                        end if;
 73	
 74	                    when S_SENDING =>
 75	                        if clk_cnt = G_CLKS_PER_BIT - 1 then  -- end of current bit
 76	                            clk_cnt <= 0;
 77	                            if bit_cnt = C_LAST_BIT then      -- stop bit finished
 78	                                txd_reg  <= '1';
 79	                                done_reg <= '1';
 80	                                state    <= S_IDLE;
 81	                            else
 82	                                bit_cnt   <= bit_cnt + 1;
 83	                                shift_reg <= '1' & shift_reg(C_LAST_BIT downto 1);
 84	                                txd_reg   <= shift_reg(1);    -- next bit on the line
 85	                            end if;
 86	                        else
 87	                            clk_cnt <= clk_cnt + 1;
 88	                        end if;
 89	
 90	                    when others =>
 91	                        state <= S_IDLE;
 92	
 93	                end case;
 94	            end if;
 95	        end if;
 96	    end process;
 97	
 98	    txd_out     <= txd_reg;
 99	    tx_done_out <= done_reg;
100	
101	end architecture rtl;

