     1	--------------------------------------------------------------------------------
     2	-- debug.vhd
     3	-- Purpose : Lab-DEBUG. Reads 2^N 32-bit words from the read-only port of a
     4	--           memory and sends them over UART (8N1) framed by a start word
     5	--           0x55AACC03 and an end word 0xAA5503CC. Every 32-bit word is sent
     6	--           most-significant byte first.
     7	-- Design  : docs/architecture/subsystems/debug.md (v0.2) §6-§15
     8	-- Reqs    : REQ-DEBUG-001..014, REQ-DEBUG-019, REQ-IF-002/003/006/007
     9	-- Author  : Hande Eryilmaz
    10	-- AI      : AI-assisted (Claude Opus 5.5, claude.ai chat, 2026-09-26), AI-0004
    11	--
    12	-- Handshake (INTERFACES.md §2)
    13	--   * ready_out = '1' after reset and while idle, '0' while a transfer runs.
    14	--   * ready_out falls at the rising edge that samples start_in = '1'.
    15	--   * start_in is only evaluated in S_IDLE -> pulses during a transfer are ignored.
    16	--   * ready_out rises two clocks after the last stop bit has ended.
    17	-- Memory timing (debug.md §9, §12)
    18	--   * mem_addr_out is a register and is held constant while a word is sent.
    19	--   * mem_data_in is captured G_MEM_LATENCY + 1 edges after the address update.
    20	--     Waiting longer than the real latency is safe; waiting shorter is not.
    21	--------------------------------------------------------------------------------
    22	library ieee;
    23	use ieee.std_logic_1164.all;
    24	use ieee.numeric_std.all;
    25	
    26	entity debug is
    27	    generic (
    28	        N             : positive := 14;              -- address width -> 2^N words (TA Q-07, DEC-012)
    29	        G_CLK_FREQ_HZ : positive := 100_000_000;     -- clock_in frequency
    30	        G_BAUD_RATE   : positive := 1_000_000;       -- DEC-005
    31	        G_MEM_LATENCY : positive := 2                -- memory read latency in clocks (debug.md §12)
    32	    );
    33	    port (
    34	        clock_in     : in  std_logic;
    35	        reset_in     : in  std_logic;                        -- active high, synchronous
    36	        start_in     : in  std_logic;                        -- 1-cycle pulse
    37	        mem_addr_out : out std_logic_vector(N - 1 downto 0); -- memory read address
    38	        mem_data_in  : in  std_logic_vector(31 downto 0);    -- memory read data
    39	        txd_out      : out std_logic;                        -- UART serial output
    40	        ready_out    : out std_logic                         -- '1' idle, '0' busy
    41	    );
    42	end entity debug;
    43	
    44	architecture rtl of debug is
    45	
    46	    constant C_CLKS_PER_BIT : positive := (G_CLK_FREQ_HZ + G_BAUD_RATE / 2) / G_BAUD_RATE;
    47	    constant C_START_WORD   : std_logic_vector(31 downto 0) := x"55AACC03";  -- REQ-DEBUG-005
    48	    constant C_END_WORD     : std_logic_vector(31 downto 0) := x"AA5503CC";  -- REQ-DEBUG-006
    49	    constant C_LAST_BYTE    : natural := 3;                                  -- 4 bytes per word
    50	    constant C_LAST_ADDR    : unsigned(N - 1 downto 0) := (others => '1');   -- 2^N - 1
    51	
    52	    type t_state is (S_IDLE, S_SEND_BYTE, S_WAIT_BYTE, S_NEXT_WORD, S_MEM_WAIT);
    53	    type t_phase is (PH_HDR, PH_DATA, PH_END);
    54	
    55	    signal state     : t_state := S_IDLE;
    56	    signal phase     : t_phase := PH_HDR;
    57	    signal word_reg  : std_logic_vector(31 downto 0) := (others => '0');  -- byte shift register
    58	    signal byte_cnt  : natural range 0 to C_LAST_BYTE := 0;
    59	    signal lat_cnt   : natural range 0 to G_MEM_LATENCY := 0;
    60	    signal addr_reg  : unsigned(N - 1 downto 0) := (others => '0');
    61	    signal ready_reg : std_logic := '1';
    62	
    63	    signal tx_start  : std_logic;
    64	    signal tx_done   : std_logic;
    65	
    66	begin
    67	
    68	    assert C_CLKS_PER_BIT >= 4
    69	        report "debug: G_CLK_FREQ_HZ / G_BAUD_RATE must be >= 4" severity failure;
    70	
    71	    ------------------------------------------------------------ word/frame FSM
    72	    fsm : process (clock_in)
    73	    begin
    74	        if rising_edge(clock_in) then
    75	            if reset_in = '1' then
    76	                state     <= S_IDLE;
    77	                phase     <= PH_HDR;
    78	                word_reg  <= (others => '0');
    79	                byte_cnt  <= 0;
    80	                lat_cnt   <= 0;
    81	                addr_reg  <= (others => '0');
    82	                ready_reg <= '1';
    83	            else
    84	                case state is
    85	
    86	                    when S_IDLE =>
    87	                        ready_reg <= '1';
    88	                        if start_in = '1' then
    89	                            word_reg  <= C_START_WORD;
    90	                            phase     <= PH_HDR;
    91	                            byte_cnt  <= 0;
    92	                            addr_reg  <= (others => '0');
    93	                            ready_reg <= '0';
    94	                            state     <= S_SEND_BYTE;
    95	                        end if;
    96	
    97	                    when S_SEND_BYTE =>              -- tx_start = '1' in this cycle
    98	                        state <= S_WAIT_BYTE;
    99	
   100	                    when S_WAIT_BYTE =>
   101	                        if tx_done = '1' then
   102	                            if byte_cnt = C_LAST_BYTE then
   103	                                state <= S_NEXT_WORD;
   104	                            else
   105	                                word_reg <= word_reg(23 downto 0) & x"00";  -- next byte to the top
   106	                                byte_cnt <= byte_cnt + 1;
   107	                                state    <= S_SEND_BYTE;
   108	                            end if;
   109	                        end if;
   110	
   111	                    when S_NEXT_WORD =>
   112	                        byte_cnt <= 0;
   113	                        lat_cnt  <= 0;
   114	                        case phase is
   115	                            when PH_HDR =>                   -- header sent, read address 0
   116	                                phase <= PH_DATA;
   117	                                state <= S_MEM_WAIT;
   118	                            when PH_DATA =>
   119	                                if addr_reg = C_LAST_ADDR then  -- last data word sent
   120	                                    word_reg <= C_END_WORD;
   121	                                    phase    <= PH_END;
   122	                                    state    <= S_SEND_BYTE;
   123	                                else
   124	                                    addr_reg <= addr_reg + 1;
   125	                                    state    <= S_MEM_WAIT;
   126	                                end if;
   127	                            when PH_END =>                   -- end word sent
   128	                                ready_reg <= '1';
   129	                                state     <= S_IDLE;
   130	                        end case;
   131	
   132	                    when S_MEM_WAIT =>
   133	                        if lat_cnt = G_MEM_LATENCY then
   134	                            word_reg <= mem_data_in;
   135	                            state    <= S_SEND_BYTE;
   136	                        else
   137	                            lat_cnt <= lat_cnt + 1;
   138	                        end if;
   139	
   140	                    when others =>
   141	                        state <= S_IDLE;
   142	
   143	                end case;
   144	            end if;
   145	        end if;
   146	    end process fsm;
   147	
   148	    tx_start <= '1' when state = S_SEND_BYTE else '0';
   149	
   150	    ------------------------------------------------------------- byte transmitter
   151	    u_uart_tx : entity work.uart_tx
   152	        generic map (
   153	            G_CLKS_PER_BIT => C_CLKS_PER_BIT
   154	        )
   155	        port map (
   156	            clock_in    => clock_in,
   157	            reset_in    => reset_in,
   158	            tx_start_in => tx_start,
   159	            tx_data_in  => word_reg(31 downto 24),   -- MSB byte first (REQ-DEBUG-007)
   160	            txd_out     => txd_out,
   161	            tx_done_out => tx_done
   162	        );
   163	
   164	    mem_addr_out <= std_logic_vector(addr_reg);
   165	    ready_out    <= ready_reg;
   166	
   167	end architecture rtl;

